import java.util.*;
import java.io.*;
import java.math.*;

public class Main {
    public static void main(String[] args) {
        new Main().run();
    }

    private void run() {
        try (InputStream inputStream = System.in;
             OutputStream outputStream = System.out) {
            InputReader in = new InputReader(inputStream);
            OutputWriter out = new OutputWriter(outputStream);
            Task solver = new TaskC();
            solver.solve(1, in, out);
            out.close();
        }
    }
}

interface Task {
    void solve(int testNumber, InputReader in, OutputWriter out);
}

class TaskA implements Task {
    public void solve(int testNumber, InputReader in, OutputWriter out) {
        int n = in.readInt(), a = 0;
        for (int i = 1; i <= n; i++) a ^= i;
        for (int i = 1; i < n; i++) a ^= in.readInt();
        out.printLine(a);
    }
}

class TaskB implements Task {
    int[] arr;
    LinkedList<Pair<Integer, Integer>> mais = new LinkedList<>();
    LinkedList<Pair<Integer, Integer>> menos = new LinkedList<>();

    public void solve(int testNumber, InputReader in, OutputWriter out) {
        int n = in.readInt();
        long ret = 0L, c = 0L;
        arr = IOUtils.readIntArray(in, n);
        for (int i = 0; i < n; i++) c += arr[i];
        c /= n;
        for (int i = 0; i < n; i++) {
            if (arr[i] < c) menos.addLast(Pair.makePair((int)c - arr[i], i));
            else mais.addLast(Pair.makePair(arr[i] - (int)c, i));
        }
        while (!mais.isEmpty() && !menos.isEmpty()) {
            int x = mais.getFirst().first, y = menos.getFirst().first, d = Math.abs(mais.getFirst().second - menos.getFirst().second);
            ret += 1L * Math.min(x, y) * d;
            if (x == y) {
                mais.removeFirst();
                menos.removeFirst();
            } else if (x < y) {
                mais.removeFirst();
                menos.set(0, Pair.makePair(y - x, menos.getFirst().second));
            } else {
                mais.set(0, Pair.makePair(x - y, mais.getFirst().second));
                menos.removeFirst();
            }
        }
        out.printLine(ret);
    }
}

class TaskC implements Task {
    ArrayList<Integer> list = new ArrayList<>();
    long[] pow = new long[16];

    public void solve(int testNumber, InputReader in, OutputWriter out) {
        pow[0] = 1L;
        for (int i = 1; i < 16; i++) pow[i] = 10L * pow[i-1] + 1L;
        out.printLine(f(in.readLong()));
    }

    int f(long n) {
        if (n <= 1L) return (int)n;
        int pos = 15, x = 0;
        for (; pos >= 0 && pow[pos] >= n; pos--);
        pos++;
        long m1 = 0L, m2 = pow[pos];
        int x1 = 0, x2 = pos + 1;
        while (m1 + pow[pos-1] <= n) {
            m1 += pow[pos-1];
            x1 += pos;
        }
        while (m2 - pow[pos-1] >= n) {
            m2 -= pow[pos-1];
            x2 += pos;
        }
        x1 += f(n - m1);
        x2 += f(m2 - n);
        return Math.min(x1, x2);
    }
}

class TaskD implements Task {
    ArrayList<Pair<Integer, Pair<Integer, Integer>>> edges = new ArrayList<>();
    int[] pai, tam;

    public void solve(int testNumber, InputReader in, OutputWriter out) {
        int n = in.readInt(), m = in.readInt();
        int[] a = IOUtils.readIntArray(in, n);
        for (int i = 0; i < m; i++) {
            int x = in.readInt() - 1, y = in.readInt() - 1;
            edges.add(Pair.makePair(Math.min(a[x], a[y]), Pair.makePair(x, y)));
        }
        pai = new int[n];
        tam = new int[n];
        Collections.sort(edges);
        Collections.reverse(edges);
        out.printLine(2.0 * kruskal(n) / n / (n - 1));
    }

    double kruskal(int n) {
        long ret = 0L;
        for (int i = 0; i < n; i++) pai[i] = i;
        Arrays.fill(tam, 1);
        for (Pair<Integer, Pair<Integer, Integer>> par : edges) {
            int w = par.first, x = par.second.first, y = par.second.second;
            if (find(x) != find(y)) {
                ret += 1L * w * tam[find(x)] * tam[find(y)];
                if (tam[find(x)] < tam[find(y)]) {
                    tam[find(y)] += tam[find(x)];
                    pai[find(x)] = find(y);
                } else {
                    tam[find(x)] += tam[find(y)];
                    pai[find(y)] = find(x);
                }
            }
        }
        return ret;
    }

    int find(int x) {
        if (x == pai[x]) return x;
        return pai[x] = find(pai[x]);
    }
}

class TaskE implements Task {
    long[] x, y;
    long[][] dp;
    long MOD = 1000000007L;
    Polygon polygon;
    Point[] points;

    public void solve(int testNumber, InputReader in, OutputWriter out) {
        int n = in.readInt();
        x = new long[n];
        y = new long[n];
        IOUtils.readLongArrays(in, x, y);
        points = new Point[n];
        for (int i = 0; i < n; i++) points[i] = new Point(x[i], y[i]);
        polygon = new Polygon(points);
        dp = new long[n][n];
        for (int i = 0; i < n; i++) Arrays.fill(dp[i], -1L);
        out.printLine(dp(0, n - 1));
    }

    long dp(int i, int j) {
        if (dp[i][j] != -1L) return dp[i][j];
        if (j == i + 1) return dp[i][j] = 1L;
        dp[i][j] = 0L;
        Segment segment = new Segment(points[i], points[j]);
        for (Point point : polygon.vertices) if (segment.contains(point, false)) return dp[i][j];
        for (int k = 0; k < i - 1; k++) if (segment.intersect(new Segment(points[k], points[k+1]), true) != null) return dp[i][j];
        for (int k = i + 1; k < j - 1; k++) if (segment.intersect(new Segment(points[k], points[k+1]), true) != null) return dp[i][j];
        for (int k = j + 1; k < points.length - 1; k++) if (segment.intersect(new Segment(points[k], points[k+1]), true) != null) return dp[i][j];
        if (i != 0 && j != 0 && i != points.length - 1 && j != points.length - 1) 
            if (segment.intersect(new Segment(points[0], points[points.length-1]), true) != null) return dp[i][j];
        Point middle = new Point(0.5 * (points[i].x + points[j].x), 0.5 * (points[i].y + points[j].y));
        if (!polygon.contains(middle)) return dp[i][j] = 0L;
        for (int k = i + 1; k < j; k++) dp[i][j] = (dp[i][j] + dp(i, k) * dp(k, j) % MOD) % MOD;
        return dp[i][j];
    }

    class Polygon {
        public final Point[] vertices;
        private Segment[] sides;

        public Polygon(Point... vertices) {
            this.vertices = vertices.clone();
        }

        public double square() {
            double sum = 0;
            for (int i = 1; i < vertices.length; i++)
                sum += (vertices[i].x - vertices[i - 1].x) * (vertices[i].y + vertices[i - 1].y);
            sum += (vertices[0].x - vertices[vertices.length - 1].x) * (vertices[0].y + vertices[vertices.length - 1].y);
            return Math.abs(sum) / 2;
        }

        public Point center() {
            double sx = 0, sy = 0;
            for (Point point : vertices) {
                sx += point.x;
                sy += point.y;
            }
            return new Point(sx / vertices.length, sy / vertices.length);
        }

        public boolean contains(Point point) {
            return contains(point, false);
        }

        public boolean contains(Point point, boolean strict) {
            for (Segment segment : sides()) {
                if (segment.contains(point, true)) return !strict;
            }
            double totalAngle = GeometryUtils.canonicalAngle(Math.atan2(vertices[0].y - point.y, vertices[0].x - point.x) - Math.atan2(vertices[vertices.length - 1].y - point.y, vertices[vertices.length - 1].x - point.x));
            for (int i = 1; i < vertices.length; i++) {
                totalAngle += GeometryUtils.canonicalAngle(Math.atan2(vertices[i].y - point.y, vertices[i].x - point.x) - Math.atan2(vertices[i - 1].y - point.y, vertices[i - 1].x - point.x));
            }
            return Math.abs(totalAngle) > Math.PI;
        }

        public Segment[] sides() {
            if (sides == null) {
                sides = new Segment[vertices.length];
                for (int i = 0; i < vertices.length - 1; i++) sides[i] = new Segment(vertices[i], vertices[i + 1]);
                sides[sides.length - 1] = new Segment(vertices[vertices.length - 1], vertices[0]);
            }
            return sides;
        }

        public double perimeter() {
            double result = vertices[0].distance(vertices[vertices.length - 1]);
            for (int i = 1; i < vertices.length; i++) result += vertices[i].distance(vertices[i - 1]);
            return result;
        }
    }

    class Segment {
        public final Point a;
        public final Point b;
        private double distance = Double.NaN;
        private Line line = null;

        public Segment(Point a, Point b) {
            this.a = a;
            this.b = b;
        }

        public double length() {
            if (Double.isNaN(distance)) distance = a.distance(b);
            return distance;
        }

        public double distance(Point point) {
            double length = length();
            double left = point.distance(a);
            if (length < GeometryUtils.epsilon) return left;
            double right = point.distance(b);
            if (left * left > right * right + length * length) return right;
            if (right * right > left * left + length * length) return left;
            return point.distance(line());
        }

        public Point intersect(Segment other, boolean includeEnds) {
            Line line = line();
            Line otherLine = other.a.line(other.b);
            if (line.parallel(otherLine)) return null;
            Point intersection = line.intersect(otherLine);
            if (contains(intersection, includeEnds) && other.contains(intersection, includeEnds)) return intersection;
            else return null;
        }

        public boolean contains(Point point, boolean includeEnds) {
            if (a.equals(point) || b.equals(point)) return includeEnds;
            if (a.equals(b)) return false;
            Line line = line();
            if (!line.contains(point)) return false;
            Line perpendicular = line.perpendicular(a);
            double aValue = perpendicular.value(a);
            double bValue = perpendicular.value(b);
            double pointValue = perpendicular.value(point);
            return aValue < pointValue && pointValue < bValue || bValue < pointValue && pointValue < aValue;
        }

        public Line line() {
            if (line == null) line = a.line(b);
            return line;
        }

        public Point middle() {
            return new Point((a.x + b.x) / 2, (a.y + b.y) / 2);
        }

        public Point intersect(Line line) {
            Line selfLine = line();
            Point intersect = selfLine.intersect(line);
            if (intersect == null) return null;
            if (contains(intersect, true)) return intersect;
            return null;
        }

        public double distance(Segment other) {
            Line line = line();
            Line otherLine = other.line();
            Point p = line == null || otherLine == null ? null : line.intersect(otherLine);
            if (p != null && contains(p, true) && other.contains(p, true)) return 0;
            return Math.min(Math.min(other.distance(a), other.distance(b)), Math.min(distance(other.a), distance(other.b)));
        }
    }

    class Point {
        public final double x;
        public final double y;

        @Override
        public String toString() {
            return "(" + x + ", " + y + ")";
        }

        public Point(double x, double y) {
            this.x = x;
            this.y = y;
        }

        public Line line(Point other) {
            if (equals(other)) return null;
            double a = other.y - y;
            double b = x - other.x;
            double c = -a * x - b * y;
            return new Line(a, b, c);
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass() != o.getClass()) return false;
            Point point = (Point) o;
            return Math.abs(x - point.x) <= GeometryUtils.epsilon && Math.abs(y - point.y) <= GeometryUtils.epsilon;
        }

        @Override
        public int hashCode() {
            int result;
            long temp;
            temp = x != +0.0d ? Double.doubleToLongBits(x) : 0L;
            result = (int) (temp ^ (temp >>> 32));
            temp = y != +0.0d ? Double.doubleToLongBits(y) : 0L;
            result = 31 * result + (int) (temp ^ (temp >>> 32));
            return result;
        }

        public double distance(Point other) {
            return GeometryUtils.fastHypot(x - other.x, y - other.y);
        }

        public double distance(Line line) {
            return Math.abs(line.a * x + line.b * y + line.c);
        }

        public double value() {
            return GeometryUtils.fastHypot(x, y);
        }

        public double angle() {
            return Math.atan2(y, x);
        }

        public Point rotate(double angle) {
            double nx = x * Math.cos(angle) - y * Math.sin(angle);
            double ny = y * Math.cos(angle) + x * Math.sin(angle);
            return new Point(nx, ny);
        }
    }

    class Line {
        public final double a;
        public final double b;
        public final double c;

        public Line(Point p, double angle) {
            a = Math.sin(angle);
            b = -Math.cos(angle);
            c = -p.x * a - p.y * b;
        }

        public Line(double a, double b, double c) {
            double h = GeometryUtils.fastHypot(a, b);
            this.a = a / h;
            this.b = b / h;
            this.c = c / h;
        }

        public Point intersect(Line other) {
            if (parallel(other)) return null;
            double determinant = b * other.a - a * other.b;
            double x = (c * other.b - b * other.c) / determinant;
            double y = (a * other.c - c * other.a) / determinant;
            return new Point(x, y);
        }

        public boolean parallel(Line other) {
            return Math.abs(a * other.b - b * other.a) < GeometryUtils.epsilon;
        }

        public boolean contains(Point point) {
            return Math.abs(value(point)) < GeometryUtils.epsilon;
        }

        public Line perpendicular(Point point) {
            return new Line(-b, a, b * point.x - a * point.y);
        }

        public double value(Point point) {
            return a * point.x + b * point.y + c;
        }

        public double distance(Point center) {
            return Math.abs(value(center));
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass() != o.getClass()) return false;
            Line line = (Line) o;
            if (!parallel(line)) return false;
            if (Math.abs(a * line.c - c * line.a) > GeometryUtils.epsilon || Math.abs(b * line.c - c * line.b) > GeometryUtils.epsilon) return false;
            return true;
        }
    }
}

class GeometryUtils {
    public static double epsilon = 1e-5;

    public static double fastHypot(double... x) {
        if (x.length == 0) return 0;
        else if (x.length == 1) return Math.abs(x[0]);
        else {
            double sumSquares = 0;
            for (double value : x) sumSquares += value * value;
            return Math.sqrt(sumSquares);
        }
    }

    public static double fastHypot(double x, double y) {
        return Math.sqrt(x * x + y * y);
    }

    public static double canonicalAngle(double angle) {
        while (angle > Math.PI) angle -= 2 * Math.PI;
        while (angle < -Math.PI) angle += 2 * Math.PI;
        return angle;
    }
}

class OutputWriter {
